17	export const scanRepositoryTool = new DynamicStructuredTool({
18	  name: "scan_repository",
19	  description:
20	    "Scan a codebase for AI indicators using FRAI's static detectors. Provide a relative path when scanning outside the current working directory.",
21	  schema,
22	  func: async ({ root }) => {
23	    const cwd = resolveWorkingDirectory(root);
24	    const result = Scanners.scanCodebase({ root: cwd });
25	
26	    const aiFiles = result.aiFiles.map((file) => path.relative(cwd, file));
27	    // aiLibraryMatches structure: { [filePath]: [library1, library2, ...] }
28	    // We need to invert it to { [library]: [filePath1, filePath2, ...] }
29	    const libraryMap: Record<string, string[]> = {};
30	    for (const [filePath, libraries] of Object.entries(result.aiLibraryMatches)) {
31	      const relativePath = path.relative(cwd, filePath);
32	      for (const library of libraries as string[]) {
33	        if (!libraryMap[library]) {
34	          libraryMap[library] = [];
35	        }
36	        libraryMap[library].push(relativePath);
37	      }
38	    }
39	    const libraryMatches = Object.entries(libraryMap).map(([library, files]) => ({
40	      library,
41	      files
42	    }));
43	
44	    const summary = [
45	      `Scanned ${result.totalFiles} source files.`,
46	      aiFiles.length
47	        ? `Detected ${aiFiles.length} AI-indicative files: ${aiFiles.join(", ")}.`
48	        : "No AI-indicative files detected.",
49	      libraryMatches.length
