import {
  DEFAULT_AI_FUNCTIONS,
  DEFAULT_AI_LIBRARIES
} from './constants.js';

const uniqPush = (store, key, value) => {
  const list = store[key] || (store[key] = []);
  if (!list.includes(value)) {
    list.push(value);
  }
};

const escapeRegex = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const removeComments = (code) => {
  return code
    .split('\n')
    .map((line) => {
      const hashIndex = line.indexOf('#');
      const slashIndex = line.indexOf('//');
      if (hashIndex === -1 && slashIndex === -1) return line;
      const minIndex = Math.min(
        hashIndex === -1 ? Infinity : hashIndex,
        slashIndex === -1 ? Infinity : slashIndex
      );
      return minIndex === Infinity ? line : line.substring(0, minIndex);
    })
    .join('\n');
};

const removeStrings = (code) => {
  return code.replace(/(['"`])(?:(?=(\\?))\2.)*?\1/g, '');
};

const findJSImports = (code, library) => {
  const cleaned = removeComments(removeStrings(code));
  const libraryEscaped = escapeRegex(library);
  const patterns = [
    new RegExp(`import\\s+(?:type\\s+)?(?:(?:\\{[^}]*\\}|\\*\\s+as\\s+\\w+|[\\w$]+)\\s+from\\s+)?['\`]${libraryEscaped}(?:/[^'"\`]+)?['\`]`, 'g'),
    new RegExp(`import\\s+['\`]${libraryEscaped}(?:/[^'"\`]+)?['\`]`, 'g'),
    new RegExp(`require\\s*\\(\\s*['\`]${libraryEscaped}(?:/[^'"\`]+)?['\`]\\s*\\)`, 'g'),
    new RegExp(`import\\s*\\(\\s*['\`]${libraryEscaped}(?:/[^'"\`]+)?['\`]\\s*\\)`, 'g'),
    new RegExp(`export\\s+(?:(?:\\{[^}]*\\}|\\*|type\\s+[^}]+)\\s+from\\s+|[\\w$]+\\s+from\\s+)['\`]${libraryEscaped}(?:/[^'"\`]+)?['\`]`, 'g'),
  ];
  for (const pattern of patterns) {
    if (pattern.test(cleaned)) return true;
  }
  return false;
};

const findPythonImports = (code, library) => {
  const cleaned = removeComments(removeStrings(code));
  const libraryEscaped = escapeRegex(library);
  const patterns = [
    new RegExp(`\\bimport\\s+${libraryEscaped}(?:\\s*,|\\s|$)`, 'g'),
    new RegExp(`\\bimport\\s+${libraryEscaped}\\s*as\\s+\\w+`, 'g'),
    new RegExp(`\\bimport\\s+${libraryEscaped}\\.\\w+`, 'g'),
    new RegExp(`\\bfrom\\s+${libraryEscaped}(?:\\.\\w+)*\\s+import\\s+`, 'g'),
  ];
  for (const pattern of patterns) {
    if (pattern.test(cleaned)) return true;
  }
  return false;
};

const normalizeLibraryName = (library, matchedName) => {
  if (library === '@langchain' && matchedName.startsWith('@langchain/')) {
    return '@langchain';
  }
  return library;
};

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    const fileName = filePath.split('/').pop().toLowerCase();
    const isPython = fileName.endsWith('.py') || fileName.endsWith('.ipynb');

    for (const library of libraries) {
      let matched = false;
      if (isPython) {
        matched = findPythonImports(content, library);
      } else {
        matched = findJSImports(content, library);
        if (!matched && library === '@langchain') {
          matched = findJSImports(content, '@langchain/');
        }
      }

      if (matched) {
        const normalizedLib = library === '@langchain' && content.includes('@langchain/')
          ? '@langchain'
          : library;
        uniqPush(result.aiLibraryMatches, filePath, normalizedLib);
        result.markAiFile(filePath);
      }
    }
  }
});

