import fs from 'fs';
import path from 'path';
import os from 'os';

// Create a test directory with various LLM imports
const testDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-test-'));

// Test 1: Anthropic SDK
fs.writeFileSync(path.join(testDir, 'anthropic-test.js'), `
import Anthropic from '@anthropic-ai/sdk';
const client = new Anthropic();
`);

// Test 2: Langchain
fs.writeFileSync(path.join(testDir, 'langchain-test.ts'), `
import { ChatOpenAI } from '@langchain/openai';
import { createToolsAgent } from 'langchain/agents';
`);

// Test 3: OpenAI with require
fs.writeFileSync(path.join(testDir, 'openai-require.js'), `
const OpenAI = require('openai');
`);

// Test 4: Dynamic import
fs.writeFileSync(path.join(testDir, 'dynamic-import.mjs'), `
async function loadAI() {
  const anthropic = await import('@anthropic-ai/sdk');
  return anthropic;
}
`);

// Test 5: Python Anthropic
fs.writeFileSync(path.join(testDir, 'python-test.py'), `
import anthropic
from anthropic import Anthropic
`);

// Test 6: Multi-line import
fs.writeFileSync(path.join(testDir, 'multiline.ts'), `
import type {
  MessageParam,
} from '@anthropic-ai/sdk';
`);

// Test 7: Export re-export
fs.writeFileSync(path.join(testDir, 'reexport.js'), `
export { ChatOpenAI } from '@langchain/openai';
`);

console.log('Test files created in:', testDir);
console.log('Files:');
