import fs from 'fs';
import path from 'path';
import os from 'os';
import { execSync } from 'child_process';

// Create a comprehensive test directory
const testDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-comprehensive-'));

// Create test files with all SDK variations
const testFiles = {
  'openai-import.js': `import OpenAI from 'openai';`,
  'openai-require.js': `const OpenAI = require('openai');`,
  'openai-dynamic.js': `const load = async () => { await import('openai'); };`,
  'anthropic-sdk.ts': `import Anthropic from '@anthropic-ai/sdk';`,
  'anthropic-direct.ts': `import anthropic from 'anthropic';`,
  'langchain-import.ts': `import { ChatOpenAI } from 'langchain';`,
  'langchain-scoped.ts': `import { ChatOpenAI } from '@langchain/openai';`,
  'langchain-agents.ts': `import { createToolsAgent } from '@langchain/langgraph';`,
  'python-anthropic.py': `from anthropic import Anthropic`,
  'python-langchain.py': `from langchain.llms import OpenAI`,
  'multiline.ts': `
    import type {
      MessageParam,
    } from '@anthropic-ai/sdk';
  `,
  'export-reexport.js': `
    export { ChatOpenAI } from '@langchain/openai';
  `,
  'comment-test.js': `
    // import OpenAI from 'openai';
    const x = 1;
  `,
  'string-test.js': `
    const importStr = "import OpenAI from 'openai'";
    const regularImport = await import('anthropic');
  `,
  'relative-import.js': `
    import { foo } from './openai-helper.js';
  `,
  'mjs-file.mjs': `import Anthropic from '@anthropic-ai/sdk';`,
  'cts-file.cts': `import OpenAI = require('openai');`,
  'mts-file.mts': `import { LangChain } from '@langchain/core';`,
};

for (const [filename, content] of Object.entries(testFiles)) {
  fs.writeFileSync(path.join(testDir, filename), content);
}

console.log('Test directory created:', testDir);
console.log(`Total test files: ${Object.keys(testFiles).length}\n`);

// Run the scan
console.log('Running scan...\n');
const scanCommand = `cd /private/tmp/100-tricks-runs/pilot-models/without/h4-scan-llm-sdks/r2 && node packages/frai-cli/dist/index.js scan "${testDir}" --json`;
const result = JSON.parse(execSync(scanCommand, { encoding: 'utf8' }));

console.log('Scan Results:');
console.log(`  Total files: ${result.totalFiles}`);
console.log(`  AI files detected: ${result.aiFiles.length}`);
console.log(`\nDetected files:`);
for (const file of result.aiFiles.sort()) {
  const filename = path.basename(file);
  console.log(`  - ${filename}`);
}

console.log(`\nLibrary Matches:`);
const libMap = {};
for (const [file, libs] of Object.entries(result.aiLibraryMatches || {})) {
  const filename = path.basename(file);
  if (!libMap[filename]) libMap[filename] = [];
  libMap[filename].push(...libs);
}

for (const [filename, libs] of Object.entries(libMap).sort()) {
  console.log(`  ${filename}: ${[...new Set(libs)].sort().join(', ')}`);
}

// Verify results
console.log('\n--- Verification ---');
const expectedDetections = [
  'openai-import.js',
  'openai-require.js',
  'openai-dynamic.js',
  'anthropic-sdk.ts',
  'anthropic-direct.ts',
  'langchain-import.ts',
  'langchain-scoped.ts',
  'langchain-agents.ts',
  'python-anthropic.py',
  'python-langchain.py',
  'multiline.ts',
  'export-reexport.js',
  'mjs-file.mjs',
  'cts-file.cts',
  'mts-file.mts',
];

const notExpected = [
  'comment-test.js',  // import is commented out
  'relative-import.js', // relative import
];

const detectedFiles = result.aiFiles.map(f => path.basename(f));
const missing = expectedDetections.filter(f => !detectedFiles.includes(f));
const unexpected = detectedFiles.filter(f => notExpected.includes(f));

if (missing.length > 0) {
  console.log(`❌ MISSING DETECTIONS: ${missing.join(', ')}`);
} else {
  console.log('✅ All expected files were detected');
}

if (unexpected.length > 0) {
  console.log(`❌ UNEXPECTED DETECTIONS: ${unexpected.join(', ')}`);
} else {
  console.log('✅ No false positives (comments/strings not detected)');
}

const allStringTests = detectedFiles.filter(f => f.includes('string'));
if (allStringTests.length === 1 && allStringTests[0] === 'string-test.js') {
  console.log('✅ String-test.js correctly detected (only the real import, not the string)');
}

// Clean up
fs.rmSync(testDir, { recursive: true, force: true });
console.log('\nTest directory cleaned up.');

