import fs from 'fs';
import path from 'path';
import os from 'os';
import { execSync } from 'child_process';

// Create a test directory for edge cases
const testDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-edge-'));

const testFiles = {
  'bare-import.js': `import 'openai';`,
  'submodule-openai.js': `import { parse } from 'openai/resources';`,
  'submodule-langchain.ts': `import { ChatOpenAI } from '@langchain/openai/llms';`,
  'false-positive-mock.js': `import { Mock } from 'openai-mock';`,
  'false-positive-caretaker.js': `const pkg = require('caretaker');`,
  'torch-submodule.py': `import torch.nn as nn`,
  'transformers-submodule.py': `from transformers.models.bert import BertModel`,
};

for (const [filename, content] of Object.entries(testFiles)) {
  fs.writeFileSync(path.join(testDir, filename), content);
}

console.log('Edge case test directory created:', testDir);
console.log(`Total test files: ${Object.keys(testFiles).length}\n`);

// Run the scan
const scanCommand = `cd /private/tmp/100-tricks-runs/pilot-models/without/h4-scan-llm-sdks/r2 && node packages/frai-cli/dist/index.js scan "${testDir}" --json`;
const result = JSON.parse(execSync(scanCommand, { encoding: 'utf8' }));

console.log('Scan Results:');
console.log(`  Total files: ${result.totalFiles}`);
console.log(`  AI files detected: ${result.aiFiles.length}`);

console.log(`\nDetected Libraries:`);
const detectedByFile = {};
for (const [file, libs] of Object.entries(result.aiLibraryMatches || {})) {
  const filename = path.basename(file);
  detectedByFile[filename] = libs;
  console.log(`  ${filename}: ${libs.join(', ')}`);
}

// Verification
console.log('\n--- Edge Case Verification ---');
const checks = [
  {
    name: 'Bare import detection',
    file: 'bare-import.js',
    expected: ['openai'],
    result: detectedByFile['bare-import.js'] || []
  },
  {
    name: 'Sub-module detection (openai/resources)',
    file: 'submodule-openai.js',
    expected: ['openai'],
    result: detectedByFile['submodule-openai.js'] || []
  },
  {
    name: 'Sub-module detection (@langchain/openai/llms)',
    file: 'submodule-langchain.ts',
    expected: ['@langchain'],
    result: detectedByFile['submodule-langchain.ts'] || []
  },
  {
    name: 'False positive: openai-mock should NOT match openai',
    file: 'false-positive-mock.js',
    expected: [],
    result: detectedByFile['false-positive-mock.js'] || []
  },
  {
    name: 'False positive: caretaker should NOT match',
    file: 'false-positive-caretaker.js',
    expected: [],
    result: detectedByFile['false-positive-caretaker.js'] || []
  },
  {
    name: 'Python sub-module: torch.nn',
    file: 'torch-submodule.py',
    expected: ['torch'],
    result: detectedByFile['torch-submodule.py'] || []
  },
  {
    name: 'Python from import with sub-module',
    file: 'transformers-submodule.py',
    expected: ['transformers'],
    result: detectedByFile['transformers-submodule.py'] || []
  }
];

let passed = 0;
let failed = 0;
for (const check of checks) {
  const expected = new Set(check.expected);
  const actual = new Set(check.result);
  const match = expected.size === actual.size && [...expected].every(e => actual.has(e));

  if (match) {
    console.log(`✅ ${check.name}`);
    passed++;
  } else {
    console.log(`❌ ${check.name}`);
    console.log(`   Expected: ${[...expected].sort().join(', ') || '(no detections)'}`);
    console.log(`   Got: ${[...actual].sort().join(', ') || '(no detections)'}`);
    failed++;
  }
}

console.log(`\n${passed} passed, ${failed} failed`);

// Clean up
fs.rmSync(testDir, { recursive: true, force: true });
console.log('Test directory cleaned up.');

